; readback.asm -- chapter 19: reading the VRAM, and the byte read ahead
; generated by gen19.py
        INCLUDE "msx.inc"
        OUTPUT "readback.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A word; a copy made through the RAM; then two loops that turn letters into
; small letters where they are: one sets one address, the other one for every
; byte.
buf     EQU VARS + $10          ; 10 bytes
ins     EQU VARS + $20           ; the 10 bytes the first loop's INs gave
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 1
        ld c, 2
        ld hl, l_orig
        call puts
        ld b, 4
        ld c, 2
        ld hl, l_copy
        call puts
        ld b, 7
        ld c, 2
        ld hl, l_naive
        call puts
        ld b, 10
        ld c, 2
        ld hl, l_right
        call puts
        VRAM_WRITE $1842        ; the word
        ld hl, word
        call send
cp1:    ; the copy: read 10 bytes into the RAM, write them 3 rows down
        ld a, $42
        out (VDP_CTRL), a
        ld a, $18               ; read: bit 6 is 0
        out (VDP_CTRL), a
        ld hl, buf
        ld b, 10
cp2:    nop                     ;  5
        nop                     ;  5
        in a, (VDP_DATA)        ; 12
        ld (hl), a              ;  8
        inc hl                  ;  7
        djnz cp2                ; 14: 51 a byte
        ld (hl), 0              ; the end of the text: the RAM is not cleared
        ld a, $A2
        out (VDP_CTRL), a
        ld a, $58               ; write
        out (VDP_CTRL), a
        ld hl, buf
        call send
        VRAM_WRITE $1902        ; the word again, twice more
        ld hl, word
        call send
        VRAM_WRITE $1962
        ld hl, word
        call send
nv:     ; one address, then IN, OR $20, OUT, 10 times
        ld a, $02
        out (VDP_CTRL), a
        ld a, $19               ; read: bit 6 is 0
        out (VDP_CTRL), a
        ld hl, ins
        ld b, 10
nv1:    nop                     ;  5
        in a, (VDP_DATA)        ; 12: the byte...
        ld (hl), a              ;  8: (kept, for meas19.py)
        inc hl                  ;  7
        or $20                  ;  8: ...as a small letter...
        out (VDP_DATA), a       ; 12: ...written back
        djnz nv1                ; 14
rt:     ; an address for every IN and every OUT
        ld hl, $1962
        ld b, 10
rt1:    ld a, l
        out (VDP_CTRL), a
        ld a, h                 ; read
        out (VDP_CTRL), a
        nop
        nop
        nop
        nop
        in a, (VDP_DATA)        ; the byte...
        or $20                  ; ...as a small letter...
        ld c, a
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40                  ; write
        out (VDP_CTRL), a
        ld a, c
        out (VDP_DATA), a       ; ...written back where it was
        inc hl
        djnz rt1
rt2:
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; send: the text at HL, ending in 0, to the VRAM from its current address
send:   ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ;  6
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr send                 ; 13: 51 a byte
word:        db "ABCDEFGHIJ", 0
l_orig:        db "WRITTEN:", 0
l_copy:        db "READ INTO THE RAM, WRITTEN:", 0
l_naive:        db "ONE ADDRESS: IN, OR $20, OUT:", 0
l_right:        db "AN ADDRESS FOR EVERY IN, OUT:", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
